//! **하이라이트 쿼리의 술어**(`#eq?`·`#any-of?`·`#match?`·`#lua-match?` 와 `not-` 갈래)를 평가한다 — 계획
//! editor-bundled-languages BLP. tree-sitter 는 술어를 검사하지 않고 그대로 넘긴다(`ts_query_predicates_for_pattern`). 평가하지
//! 않으면 그 패턴이 **조건 없이** 걸리고 겹친 캡처는 마지막이 이겨(§5.3), Python·Ruby·Lua 의 식별자가 전부 숫자 색이 됐다(실측
//! 2026-10-14 — 「대문자로 시작하면 상수」 같은 조건이 안 걸러졌다).
//!
//! **정규식은 부분집합만 안다** — 번들 쿼리가 쓰는 것(2026-10-14 전수: 31 종): `^`·`$`·`.`·문자 묶음 `[…]`(범위·`^` 부정·`\d` 같은
//! 이스케이프)·묶음 `(…)` 과 `|`·`*`·`+`·`?`·이스케이프(`\d`·`\w`·`\s`·`\.`). PCRE2 를 구문 모듈에 끌어오지 않는다 — 문법 C 와 같은 층에
//! 정규식 엔진을 두면 그 경계가 넓어진다. **모르는 구문을 만나면 그 술어는 «통과»다** — 종전 동작(조건 없이 걸림)과 같다. 모르는 술어
//! 이름(`#set!`·`#is-not?`·`#has-ancestor?` …)도 통과다. Lua 패턴(`#lua-match?`)은 `%` 를 이스케이프로 읽는 같은 부분집합이다.
//!
//! 정답 대조는 판정자 `PRD*` 가 Python `re` 로 뽑은 표로 한다.

const std = @import("std");

const none: u16 = std.math.maxInt(u16);

const Kind = enum(u8) { literal, any, class, group, bol, eol, digit, word, space, not_digit, not_word, not_space };
const Quant = enum(u8) { one, opt, star, plus };

const Node = struct {
    kind: Kind,
    quant: Quant = .one,
    ch: u8 = 0,
    /// 문자 묶음: 패턴 안 `[` 다음부터 `]` 앞까지(부정 `^` 는 뺀 자리).
    lo: u16 = 0,
    hi: u16 = 0,
    neg: bool = false,
    /// 묶음: 첫 갈래의 머리 노드.
    child: u16 = none,
    /// 같은 줄(sequence)의 다음 노드.
    next: u16 = none,
    /// 갈래의 머리 노드끼리 — 다음 갈래.
    alt: u16 = none,
};

/// 패턴 하나를 노드로 편 것. 노드 수에 상한이 있다(번들 쿼리의 가장 긴 패턴 — Make 의 내장 변수 목록 — 도 한참 아래다). 넘거나
/// 모르는 구문이면 `ok` 가 거짓이고, 호출자는 그 술어를 통과로 본다.
const Program = struct {
    pattern: []const u8,
    esc: u8,
    nodes: [max_nodes]Node = undefined,
    len: u16 = 0,
    head: u16 = none,
    ok: bool = true,

    const max_nodes = 1024;

    fn push(self: *Program, n: Node) u16 {
        if (self.len == max_nodes) {
            self.ok = false;
            return none;
        }
        self.nodes[self.len] = n;
        self.len += 1;
        return self.len - 1;
    }
};

const Parser = struct {
    p: *Program,
    i: usize = 0,

    fn alt(self: *Parser) u16 {
        const first = self.seq();
        var last = first;
        while (self.p.ok and self.i < self.p.pattern.len and self.p.pattern[self.i] == '|') {
            self.i += 1;
            const s = self.seq();
            if (last == none or s == none) {
                // 빈 갈래(`(a|)`)는 번들 쿼리에 없다 — 모르는 구문으로 둔다.
                self.p.ok = false;
                return none;
            }
            self.p.nodes[last].alt = s;
            last = s;
        }
        return first;
    }

    fn seq(self: *Parser) u16 {
        var head: u16 = none;
        var tail: u16 = none;
        const pat = self.p.pattern;
        while (self.p.ok and self.i < pat.len and pat[self.i] != '|' and pat[self.i] != ')') {
            const n = self.atom();
            if (!self.p.ok) return none;
            if (self.i < pat.len) {
                const q: ?Quant = switch (pat[self.i]) {
                    '*' => .star,
                    '+' => .plus,
                    '?' => .opt,
                    else => null,
                };
                if (q) |qq| {
                    const k = self.p.nodes[n].kind;
                    // 앵커에 수량자, 반복 묶음(`(…)*`·`(…)+`)은 모른다 — 번들 쿼리에 없다(`(…)?` 는 받는다).
                    if (k == .bol or k == .eol or (k == .group and qq != .opt)) {
                        self.p.ok = false;
                        return none;
                    }
                    self.p.nodes[n].quant = qq;
                    self.i += 1;
                    // `a*?`·`a+*` 같은 겹친 수량자는 모른다.
                    if (self.i < pat.len and (pat[self.i] == '*' or pat[self.i] == '+' or pat[self.i] == '?')) {
                        self.p.ok = false;
                        return none;
                    }
                }
            }
            if (head == none) head = n else self.p.nodes[tail].next = n;
            tail = n;
        }
        return head;
    }

    fn atom(self: *Parser) u16 {
        const pat = self.p.pattern;
        const b = pat[self.i];
        self.i += 1;
        if (b == self.p.esc) {
            if (self.i >= pat.len) {
                self.p.ok = false;
                return none;
            }
            const e = pat[self.i];
            self.i += 1;
            return self.p.push(escapeNode(e, self.p.esc == '%'));
        }
        switch (b) {
            '.' => return self.p.push(.{ .kind = .any }),
            '^' => return self.p.push(.{ .kind = .bol }),
            '$' => return self.p.push(.{ .kind = .eol }),
            '(' => {
                const g = self.p.push(.{ .kind = .group });
                if (g == none) return none;
                const child = self.alt();
                if (!self.p.ok or self.i >= pat.len or pat[self.i] != ')' or child == none) {
                    self.p.ok = false;
                    return none;
                }
                self.i += 1;
                self.p.nodes[g].child = child;
                return g;
            },
            '[' => {
                var neg = false;
                if (self.i < pat.len and pat[self.i] == '^') {
                    neg = true;
                    self.i += 1;
                }
                const lo = self.i;
                // `]` 를 찾는다 — 이스케이프 뒤 글자는 건너뛴다. 첫 글자 `]` 는 번들 쿼리에 없다.
                while (self.i < pat.len and pat[self.i] != ']') : (self.i += 1) {
                    if (pat[self.i] == self.p.esc) self.i += 1;
                }
                if (self.i >= pat.len or self.i == lo) {
                    self.p.ok = false;
                    return none;
                }
                const hi = self.i;
                self.i += 1;
                return self.p.push(.{ .kind = .class, .lo = @intCast(lo), .hi = @intCast(hi), .neg = neg });
            },
            ')', '*', '+', '?', '{', '}' => {
                self.p.ok = false; // `{n,m}` 같은 반복 횟수·짝 없는 괄호는 모른다
                return none;
            },
            else => return self.p.push(.{ .kind = .literal, .ch = b }),
        }
    }
};

/// `\d`·`%d` 같은 이스케이프. Lua 는 `%a`(글자)·`%l`(소문자)·`%u`(대문자)도 있다 — 번들 쿼리에 없어 글자 그대로로 읽지 않고 모르는
/// 구문으로 두는 대신, 흔한 셋만 받는다.
fn escapeNode(e: u8, lua: bool) Node {
    return switch (e) {
        'd' => .{ .kind = .digit },
        'w' => .{ .kind = .word },
        's' => .{ .kind = .space },
        'D' => .{ .kind = .not_digit },
        'W' => .{ .kind = .not_word },
        'S' => .{ .kind = .not_space },
        else => if (lua and e == 'a') .{ .kind = .class, .lo = 0, .hi = 0 } else .{ .kind = .literal, .ch = e },
    };
}

fn isWord(b: u8) bool {
    return std.ascii.isAlphanumeric(b) or b == '_';
}

fn classHas(pat: []const u8, lo: usize, hi: usize, esc: u8, b: u8) bool {
    var i = lo;
    while (i < hi) {
        var c0 = pat[i];
        if (c0 == esc and i + 1 < hi) {
            const e = pat[i + 1];
            i += 2;
            const hit = switch (e) {
                'd' => std.ascii.isDigit(b),
                'w' => isWord(b),
                's' => std.ascii.isWhitespace(b),
                'a' => if (esc == '%') std.ascii.isAlphabetic(b) else b == 'a',
                else => b == e,
            };
            if (hit) return true;
            continue;
        }
        c0 = pat[i];
        if (i + 2 < hi and pat[i + 1] == '-') {
            if (b >= c0 and b <= pat[i + 2]) return true;
            i += 3;
            continue;
        }
        if (b == c0) return true;
        i += 1;
    }
    return false;
}

/// 계속할 자리 — 묶음 안의 갈래가 끝나면 묶음 뒤로 간다.
const Cont = struct { idx: u16, parent: ?*const Cont };

const Matcher = struct {
    p: *const Program,
    text: []const u8,
    /// 되돌아가기 걸음 상한 — 병적인 패턴·입력에서 키 하나에 멈추지 않게. 넘으면 «통과»(모르는 구문과 같은 쪽).
    steps: u32 = 0,
    exhausted: bool = false,

    const max_steps: u32 = 200_000;

    fn one(self: *Matcher, n: Node, pos: usize) bool {
        if (pos >= self.text.len) return false;
        const b = self.text[pos];
        return switch (n.kind) {
            .literal => b == n.ch,
            .any => b != '\n',
            .class => blk: {
                // Lua `%a` 를 노드 하나로 편 자리(lo = hi = 0).
                const has = if (n.lo == 0 and n.hi == 0) std.ascii.isAlphabetic(b) else classHas(self.p.pattern, n.lo, n.hi, self.p.esc, b);
                break :blk has != n.neg;
            },
            .digit => std.ascii.isDigit(b),
            .word => isWord(b),
            .space => std.ascii.isWhitespace(b),
            .not_digit => !std.ascii.isDigit(b),
            .not_word => !isWord(b),
            .not_space => !std.ascii.isWhitespace(b),
            .group, .bol, .eol => unreachable,
        };
    }

    fn m(self: *Matcher, idx: u16, pos: usize, k: ?*const Cont) bool {
        self.steps += 1;
        if (self.steps > max_steps) {
            self.exhausted = true;
            return false;
        }
        if (idx == none) {
            if (k) |c| return self.m(c.idx, pos, c.parent);
            return true; // 찾기 — 패턴 끝에 닿으면 맞다(`$` 는 노드가 잰다)
        }
        const n = self.p.nodes[idx];
        switch (n.kind) {
            .bol => return pos == 0 and self.m(n.next, pos, k),
            .eol => return pos == self.text.len and self.m(n.next, pos, k),
            .group => return self.group(n, pos, k),
            else => {},
        }
        switch (n.quant) {
            .one => return self.one(n, pos) and self.m(n.next, pos + 1, k),
            .opt => return (self.one(n, pos) and self.m(n.next, pos + 1, k)) or self.m(n.next, pos, k),
            .star, .plus => {
                var count: usize = 0;
                while (self.one(n, pos + count)) count += 1;
                const min: usize = if (n.quant == .plus) 1 else 0;
                if (count < min) return false;
                var c = count;
                while (true) : (c -= 1) {
                    if (self.m(n.next, pos + c, k)) return true;
                    if (self.exhausted or c == min) return false;
                }
            },
        }
    }

    fn group(self: *Matcher, n: Node, pos: usize, k: ?*const Cont) bool {
        const after: Cont = .{ .idx = n.next, .parent = k };
        return switch (n.quant) {
            .one => self.alts(n.child, pos, &after),
            .opt => self.alts(n.child, pos, &after) or (!self.exhausted and self.m(n.next, pos, k)),
            .star, .plus => unreachable, // 파서가 거른다
        };
    }

    fn alts(self: *Matcher, head: u16, pos: usize, after: *const Cont) bool {
        var cur = head;
        while (cur != none) : (cur = self.p.nodes[cur].alt) {
            if (self.m(cur, pos, after)) return true;
            if (self.exhausted) return false;
        }
        return false;
    }
};

/// `text` 가 `pattern` 에 맞는가(찾기 — 어디서든; `^`·`$` 로 묶는다). `lua` 면 `%` 가 이스케이프다. 모르는 구문·걸음 상한이면 `null`
/// — 호출자는 통과로 본다.
pub fn search(pattern: []const u8, lua: bool, text: []const u8) ?bool {
    var prog: Program = .{ .pattern = pattern, .esc = if (lua) '%' else '\\' };
    var parser: Parser = .{ .p = &prog };
    prog.head = parser.alt();
    if (!prog.ok or parser.i != pattern.len) return null;
    if (prog.head == none) return true; // 빈 패턴은 늘 맞다
    var start: usize = 0;
    while (start <= text.len) : (start += 1) {
        var mt: Matcher = .{ .p = &prog, .text = text };
        if (mt.m(prog.head, start, null)) return true;
        if (mt.exhausted) return null;
        // `^` 로 시작하면 0 에서만 맞을 수 있다.
        if (prog.nodes[prog.head].kind == .bol and prog.nodes[prog.head].alt == none) break;
    }
    return false;
}

// ── 판정자 ────────────────────────────────────────────────────────────────────

const testing = std.testing;

test "PRD1 정규식 부분집합 — 번들 쿼리가 쓰는 꼴의 기본 동작" {
    try testing.expectEqual(@as(?bool, true), search("^[A-Z]", false, "Foo"));
    try testing.expectEqual(@as(?bool, false), search("^[A-Z]", false, "foo"));
    try testing.expectEqual(@as(?bool, true), search("^[A-Z][A-Z\\d_]*$", false, "MAX_2"));
    try testing.expectEqual(@as(?bool, false), search("^[A-Z][A-Z\\d_]*$", false, "Max"));
    try testing.expectEqual(@as(?bool, true), search("^(len|print|range)$", false, "print"));
    try testing.expectEqual(@as(?bool, false), search("^(len|print|range)$", false, "printer"));
    try testing.expectEqual(@as(?bool, true), search("[%\\*\\?]", false, "%.o"));
    try testing.expectEqual(@as(?bool, false), search("[%\\*\\?]", false, "main.o"));
    try testing.expectEqual(@as(?bool, true), search("^-", false, "-x"));
    try testing.expectEqual(@as(?bool, true), search("^__[A-Z][A-Z\\d_]+__$", false, "__FILE__"));
    try testing.expectEqual(@as(?bool, true), search("^\\.(PHONY|SILENT)$", false, ".PHONY"));
    try testing.expectEqual(@as(?bool, false), search("^\\.(PHONY|SILENT)$", false, "xPHONY"));
    try testing.expectEqual(@as(?bool, true), search("^_?[A-Z][A-Z\\d_]+$", false, "_AB"));
    try testing.expectEqual(@as(?bool, true), search("^_*[A-Z][A-Z\\d_]+$", false, "__AB"));
    try testing.expectEqual(@as(?bool, true), search("a.c", false, "xabcx"));
    try testing.expectEqual(@as(?bool, true), search("^[^a-z]+$", false, "ABC_1"));
    // Lua 패턴 — `%` 가 이스케이프.
    try testing.expectEqual(@as(?bool, true), search("^//!", true, "//! doc"));
    try testing.expectEqual(@as(?bool, true), search("^[A-Z_][a-zA-Z0-9_]*", true, "Foo"));
    try testing.expectEqual(@as(?bool, true), search("^%d+$", true, "123"));
    // 모르는 구문은 `null`(통과로 본다) — 반복 횟수·짝 없는 괄호.
    try testing.expectEqual(@as(?bool, null), search("^a{2}$", false, "aa"));
    try testing.expectEqual(@as(?bool, null), search("(a", false, "a"));
    try testing.expectEqual(@as(?bool, null), search("a)", false, "a"));
}

// ── 생성 표 — 번들 쿼리의 정규식(tree-sitter 문자열 해석 뒤) × 표본, 답은 Python `re.search`(생성: 계획 editor-bundled-languages BLP).
const oracle = [_]struct { p: []const u8, lua: bool, t: []const u8, want: bool }{
    .{ .p = "[%*?]", .lua = false, .t = "x", .want = false },
    .{ .p = "[%*?]", .lua = false, .t = "Foo", .want = false },
    .{ .p = "[%*?]", .lua = false, .t = "FOO", .want = false },
    .{ .p = "[%*?]", .lua = false, .t = "FOO_BAR", .want = false },
    .{ .p = "[%*?]", .lua = false, .t = "F", .want = false },
    .{ .p = "[%*?]", .lua = false, .t = "_A", .want = false },
    .{ .p = "[%*?]", .lua = false, .t = "__X", .want = false },
    .{ .p = "[%*?]", .lua = false, .t = "_", .want = false },
    .{ .p = "[%*?]", .lua = false, .t = "__FILE__", .want = false },
    .{ .p = "[%*?]", .lua = false, .t = "__LINE__", .want = false },
    .{ .p = "[%*?]", .lua = false, .t = "__ENCODING__", .want = false },
    .{ .p = "[%*?]", .lua = false, .t = "len", .want = false },
    .{ .p = "[%*?]", .lua = false, .t = "print", .want = false },
    .{ .p = "[%*?]", .lua = false, .t = "printer", .want = false },
    .{ .p = "[%*?]", .lua = false, .t = "range", .want = false },
    .{ .p = "[%*?]", .lua = false, .t = "append", .want = false },
    .{ .p = "[%*?]", .lua = false, .t = "CC", .want = false },
    .{ .p = "[%*?]", .lua = false, .t = "CFLAGS", .want = false },
    .{ .p = "[%*?]", .lua = false, .t = "CFLAGSX", .want = false },
    .{ .p = "[%*?]", .lua = false, .t = "all", .want = false },
    .{ .p = "[%*?]", .lua = false, .t = "clean", .want = false },
    .{ .p = "[%*?]", .lua = false, .t = "install-strip", .want = false },
    .{ .p = "[%*?]", .lua = false, .t = "%.o", .want = true },
    .{ .p = "[%*?]", .lua = false, .t = "main.o", .want = false },
