    .{ .p = "^[A-Z_][a-zA-Z0-9_]*", .lua = true, .t = "x y", .want = false },
    .{ .p = "^[A-Z_][a-zA-Z0-9_]*", .lua = true, .t = "é", .want = false },
    .{ .p = "^[A-Z_][a-zA-Z0-9_]*", .lua = true, .t = "AB'", .want = true },
};

test "PRD2 번들 쿼리의 정규식 전부 — Python `re` 의 답과 같다(표본 문자열마다)" {
    var unknown: usize = 0;
    for (oracle) |o| {
        const got = search(o.p, o.lua, o.t) orelse {
            std.debug.print("모르는 구문: {s}\n", .{o.p});
            unknown += 1;
            continue;
        };
        if (got != o.want) {
            std.debug.print("갈림: /{s}/ {s} — 우리 {} · Python {}\n", .{ o.p, o.t, got, o.want });
            return error.RegexMismatch;
        }
    }
    // 번들 쿼리의 정규식은 전부 아는 구문이어야 한다 — 모르면 그 술어는 통과(종전)로 남는다.
    try testing.expectEqual(@as(usize, 0), unknown);
}
